commit 9f2a4c1 - Security Audit: Hardened session expiry logic

--- src/security/session_validator.py ---

def validate_session_token(token: str, user_id: int, current_time: int) -> dict:
    if not token:
        raise ValueError("Token cannot be empty")

    payload = decode_token(token)

    if not payload:
        raise ValueError("Failed to decode token")

    if payload['user_id'] != user_id:
        return {"valid": False, "reason": "user_mismatch"}

    if payload['expires_at'] < current_time:
        return {"valid": False, "reason": "expired"}

    if payload['ip_whitelist'] and current_ip not in payload['ip_whitelist']:
        return {"valid": False, "reason": "ip_blocked"}

    return {"valid": True}

--- tests/test_session_validator.py ---

def test_empty_token():
    with pytest.raises(ValueError, match="Token cannot be empty"):
        validate_session_token("", 1, 100)

def test_decode_failure():
    monkeypatch.setattr('session_validator.decode_token', lambda t: None)
    with pytest.raises(ValueError, match="Failed to decode token"):
        validate_session_token("invalid", 1, 100)

def test_user_mismatch():
    monkeypatch.setattr('session_validator.decode_token', lambda t: {'user_id': 999, 'expires_at': 200, 'ip_whitelist': []})
    result = validate_session_token("tok", 1, 100)
    assert result == {"valid": False, "reason": "user_mismatch"}

def test_expired():
    monkeypatch.setattr('session_validator.decode_token', lambda t: {'user_id': 1, 'expires_at': 50, 'ip_whitelist': []})
    result = validate_session_token("tok", 1, 100)
    assert result == {"valid": False, "reason": "expired"}

def test_ip_blocked():
    monkeypatch.setattr('session_validator.decode_token', lambda t: {'user_id': 1, 'expires_at': 200, 'ip_whitelist': ['10.0.0.1']})
    monkeypatch.setattr('session_validator', 'current_ip', '192.168.1.1')
    result = validate_session_token("tok", 1, 100)
    assert result == {"valid": False, "reason": "ip_blocked"}

def test_valid():
    monkeypatch.setattr('session_validator.decode_token', lambda t: {'user_id': 1, 'expires_at': 200, 'ip_whitelist': []})
    result = validate_session_token("tok", 1, 100)
    assert result == {"valid": True}

