--- firmware/battery/aggregator.c ---

int aggregate_battery_data(const sensor_packet_t* packets, int count, battery_summary_t* out) {
    if (count <= 0) return -1;
    if (!packets || !out) return -2;

    double sum_v = 0.0;
    int valid = 0;

    for (int i = 0; i < count; i++) {
        if (packets[i].status != SENSOR_OK) continue;
        sum_v += packets[i].voltage;
        valid++;
    }

    if (valid == 0) return -3;

    out->avg_voltage = sum_v / valid;
    out->valid_count = valid;
    out->total_packets = count;
    return 0;
}

--- tests/test_aggregator.py ---

import pytest

@pytest.mark.parametrize("count, expected", [
    (1, 0),
