import logging
from datetime import datetime

logger = logging.getLogger(__name__)


def calculate_monthly_charges(customer_id: int, usage_records: list, tariff: dict) -> float:
    """Calculate monthly charges based on usage and tariff plan."""
    total = 0.0
    for record in usage_records:
        if record['type'] == 'data':
            if record['mb'] > tariff.get('data_free_mb', 0):
                excess_mb = record['mb'] - tariff['data_free_mb']
                total += excess_mb * tariff['data_rate_per_mb']
        elif record['type'] == 'voice':
            if record['minutes'] > tariff.get('voice_free_min', 0):
                excess_min = record['minutes'] - tariff['voice_free_min']
                total += excess_min * tariff['voice_rate_per_min']
        elif record['type'] == 'sms':
            total += record['count'] * tariff.get('sms_rate', 0.1)

    if total > tariff.get('monthly_cap', float('inf')):
        total = tariff['monthly_cap']

    logger.debug(f"Charges for {customer_id}: {total}")
    return round(total, 2)


def apply_discount(base_amount: float, discount_pct: float) -> float:
    """Apply percentage discount to base amount."""
    if discount_pct <= 0:
        return base_amount
    discount_amount = base_amount * (discount_pct / 100.0)
    return round(base_amount - discount_amount, 2)


