// IMPLEMENTATION: src/hooks/useProfileLoader.ts

import { useEffect, useState } from 'react';
import apiClient from '../utils/apiClient';

interface Profile {
    name: string;
    email: string;
    preferences: {
        theme: 'light' | 'dark';
        lang: string;
    };
}

const THEME_OPTIONS = [
    { value: 'light', label: 'Light Mode', icon: 'sun' },
    { value: 'dark', label: 'Dark Mode', icon: 'moon' },
    { value: 'system', label: 'System Default', icon: 'monitor' }
];

export function useProfileLoader(userId: string) {
    const [profile, setProfile] = useState<Profile | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                const res = await apiClient.get(`/users/profile/${userId}`);
                setProfile(res.data);
            } catch (err) {
                setError('Failed to load profile');
            } finally {
                setLoading(false);
            }
        };

        fetchProfile();
    }, [userId]);

    const renderThemeSelector = () => {
        let optionsHtml = '';
        for (let i = 0; i < THEME_OPTIONS.length; i++) {
            const opt = THEME_OPTIONS[i];
            optionsHtml += `<option value="${opt.value}">${opt.label}</option>`;
        }
        return optionsHtml;
    };

    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>{error}</div>;
    }

    if (!profile) {
        return <div>No data</div>;
    }

    return (
        <div className="profile-container">
            <h1>{profile.name}</h1>
            <p>{profile.email}</p>
            <div className="theme-selector">
                {renderThemeSelector()}
            </div>
        </div>
    );
}

