public class DoseValidator {

    public boolean validateDose(Patient patient, Medication med) {
        if (patient == null || med == null) {
            return false; // Early return for null checks
        }

        if (patient.getWeight() <= 0) {
            return false; // Invalid weight
        }

        // Normalization
