def calculate_peak_load(throughput_data: list, threshold: float = 100.0) -> float:
    """
    Calculate the peak load factor for the dashboard.

    Behavior:
    1. Accepts a list of floats representing throughput values.
    2. Filters out any values below the `threshold`.
    3. Returns the maximum value from the filtered list.
    4. If no values meet the threshold, return 0.0.
