function calculatePercentile(data, percentile) {
    // Validate percentile range
    if (percentile < 0 || percentile > 100) {
        throw new Error("Percentile must be between 0 and 100");
    }

    // Filter out nulls and convert to numbers
    const cleanData = data.filter(v => v !== null && v !== undefined).map(Number);

    if (cleanData.length === 0) return 0;

    // Sort in place (Efficiency optimization)
    cleanData.sort((a, b) => a - b);

    // Calculate index
    // Formula: ceil((percentile / 100) * n) - 1
    const index = Math.ceil((percentile / 100) * cleanData.length) - 1;

    // Boundary check
    if (index < 0) return cleanData[0];
    if (index >= cleanData.length) return cleanData[cleanData.length - 1];

    return cleanData[index];
}

