/**
 * validateQuizSubmission(studentAnswers, timeRemaining, isFinalAttempt)
 * Validates a student's quiz submission against business rules.
 * Returns: { isValid: boolean, errors: string[], score: number }
 * 
 * Rules:
 * 1. If timeRemaining <= 0, submission invalid (time's up)
 * 2. If studentAnswers is empty array, invalid (must answer something)
 * 3. If isFinalAttempt is true AND any answer is null/undefined, invalid (final must be complete)
 * 4. If more than 50% answers are identical strings, flag as possible cheating (still valid but with warning)
 * 5. Auto-grading: each non-null answer contributes 1 point, null answers are 0
 * 6. Special: if timeRemaining < 30 seconds, apply time pressure bonus: +5% to score
 * 7. Special: if isFinalAttempt AND score < 60, invalid (failing final not allowed)
 */

function validateQuizSubmission(studentAnswers, timeRemaining, isFinalAttempt) {
  const result = { isValid: true, errors: [], score: 0 };

  // Branch 1: Time check
  if (timeRemaining <= 0) {
    result.isValid = false;
    result.errors.push("Time has expired");
    return result;
  }

  // Branch 2: Empty answers
  if (!studentAnswers || studentAnswers.length === 0) {
    result.isValid = false;
    result.errors.push("No answers provided");
    return result;
  }

  // Branch 3: Final attempt completeness
  if (isFinalAttempt) {
    const hasNull = studentAnswers.some(ans => ans === null || ans === undefined);
    if (hasNull) {
      result.isValid = false;
      result.errors.push("Final attempt must have all questions answered");
      return result;
    }
  }

  // Calculate base score
  const answeredCount = studentAnswers.filter(ans => ans !== null && ans !== undefined).length;
  result.score = answeredCount;

  // Branch 4: Cheating detection
  if (studentAnswers.length > 0) {
    const answerCounts = {};
    studentAnswers.forEach(ans => {
      if (ans !== null && ans !== undefined) {
        answerCounts[ans] = (answerCounts[ans] || 0) + 1;
      }
    });

    const maxCount = Math.max(...Object.values(answerCounts));
    if (maxCount / studentAnswers.length > 0.5) {
      result.errors.push("Warning: Possible pattern repetition detected");
    }
  }

  // Branch 5: Time pressure bonus
  if (timeRemaining < 30) {
    result.score = Math.floor(result.score * 1.05);
  }

  // Branch 6: Final attempt minimum score
  if (isFinalAttempt && result.score < 60) {
    result.isValid = false;
    result.errors.push("Final attempt score below passing threshold");
  }

  return result;
}

/**
 * Branches the function has:
 * 1. timeRemaining <= 0 -> invalid (time's up)
 * 2. empty studentAnswers array -> invalid (no answers)
 * 3. isFinalAttempt true with null answers -> invalid (incomplete final)
 * 4. >50% identical answers -> warning added (cheating detection)
 * 5. Normal score calculation (base path)
 * 6. timeRemaining < 30 seconds -> apply 5% bonus
 * 7. isFinalAttempt with score < 60 -> invalid (failing final)
 * 8. Error path: null/undefined studentAnswers parameter
 * 9. Error path: negative timeRemaining
 */

/**
 * Unit tests - parameterized approach
 */

describe('validateQuizSubmission', () => {
  const testCases = [
    {
      name: 'normal submission',
      answers: ['A', 'B', 'C'],
      time: 120,
      final: false,
      // Expected: should be valid with score 3
    },
    {
      name: 'time pressure bonus',
      answers: ['A', 'B', 'C', 'D'],
      time: 25,
      final: false,
      // Expected: should be valid with score ~4 (4 * 1.05 = 4.2 -> 4)
    },
    {
