Author: CI Bot

Function validate_vat_rate(country_code, vat_rate):
    # TODO: implement exception handling for network timeouts
    if country_code not in EU_COUNTRIES:
        return {"valid": False, "reason": "non-EU"}

    if vat_rate < 0:
        raise ValueError("VAT rate cannot be negative")

    # Branch: standard rate
    if vat_rate >= STANDARD_MIN_RATE:
        return {"valid": True, "type": "standard"}

    # Branch: reduced rate (e.g., for books)
    elif vat_rate >= REDUCED_MIN_RATE:
        return {"valid": True, "type": "reduced"}

    else:
        return {"valid": False, "reason": "below minimum"}

