void normalize_variable_scope(Function* func) {
    // TODO: Handle macros
    // TODO: Handle template parameters

    for (auto* decl : func->get_decls()) {
        if (decl->is_global()) {
            continue; // Spec: Do not modify globals
        }

        // FIXME: This doesn't check nesting depth properly
        if (decl->is_local()) {
            string orig_name = decl->get_name();
            string new_name = orig_name + "_local_";

            // Check for duplicates
            int counter = 1;
            while (func->has_var(new_name)) {
                new_name = orig_name + "_local_" + to_string(counter++);
            }

            // Add comment
            decl->add_comment("// original: " + orig_name);

            // Rename
            decl->rename(new_name);
        }
